<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>Officer directory</h2><p>Manage officer access and area assignments.</p></div><IconButton icon="add" label="Create officer" @click="openCreate"/></div><div class="glass-panel"><div class="table-tools"><div class="search-box"><span>⌕</span><input v-model="search" placeholder="Search name or email" @input="load(1)"/></div><span class="muted">{{ result.totalCount||0 }} officers</span></div><div v-if="error" class="inline-alert">{{error}}</div><div v-if="loading" class="state-message">Loading officers…</div><div v-else-if="!result.items?.length" class="state-message">No land officers found.</div><div v-else class="table-scroll"><table class="glass-table"><thead><tr><th>Officer</th><th>Assigned area</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="o in result.items" :key="o.id"><td><b>{{o.fullName}}</b><small>{{o.email}}</small></td><td>{{o.assignedAreaName||'Unassigned'}}</td><td><span class="status-tag" :class="o.isActive?'good':'muted-tag'">{{o.isActive?'Active':'Inactive'}}</span></td><td class="actions"><IconButton icon="edit" label="Edit officer" @click="edit(o)"/><IconButton icon="delete" label="Delete officer" variant="danger" @click="remove(o)"/></td></tr></tbody></table></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div>
<div v-if="modal" class="glass-panel inline-form-card"><form @submit.prevent="save"><div class="modal-heading"><h3>{{editing?'Update officer':'Create officer'}}</h3><IconButton icon="cancel" label="Close" @click="modal=false"/></div><FormField label="Full name"><input v-model="form.fullName" required minlength="2"/></FormField><FormField label="Email"><input v-model="form.email" type="email" required :disabled="editing"/></FormField><FormField v-if="!editing" label="Temporary password"><input v-model="form.password" type="password" minlength="8" required/></FormField><FormField label="Assigned area"><SearchableSelect v-model="form.assignedAreaId"/></FormField><label v-if="editing" class="check-line"><input v-model="form.isActive" type="checkbox"/> Active account</label><div class="modal-actions"><IconButton icon="cancel" label="Cancel" @click="modal=false"/><IconButton icon="save" label="Save officer" type="submit" :loading="saving"/></div><p v-if="error" class="inline-alert">{{error}}</p></form></div><ConfirmDialog :open="!!pendingDelete" title="Delete land officer" :message="`Delete ${pendingDelete?.fullName}? This cannot be undone.`" confirm-label="Delete officer" danger @cancel="pendingDelete=null" @confirm="confirmRemove"/></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {platformApi} from '@/services/platform';import IconButton from '@/components/ui/IconButton.vue';import SearchableSelect from '@/components/ui/SearchableSelect.vue';import ConfirmDialog from '@/components/ui/ConfirmDialog.vue';import FormField from '@/components/ui/FormField.vue';
const result=ref<any>({items:[]}),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),modal=ref(false),editing=ref<any>(null),pendingDelete=ref<any>(null);const form=ref<any>({fullName:'',email:'',password:'',assignedAreaId:'',isActive:true});
async function load(page=1){loading.value=true;error.value='';try{result.value=(await platformApi.officers(page,search.value)).data}catch(e:any){error.value=e.response?.data?.detail||'Could not load officers'}finally{loading.value=false}}
function openCreate(){editing.value=null;form.value={fullName:'',email:'',password:'',assignedAreaId:'',isActive:true};error.value='';modal.value=true}
function edit(o:any){editing.value=o;form.value={fullName:o.fullName,email:o.email,password:'',assignedAreaId:o.assignedAreaId||'',isActive:o.isActive};error.value='';modal.value=true}
async function save(){saving.value=true;error.value='';try{const data=editing.value?{fullName:form.value.fullName,assignedAreaId:form.value.assignedAreaId||null,isActive:form.value.isActive}:{...form.value,assignedAreaId:form.value.assignedAreaId||null};if(editing.value)await platformApi.updateOfficer(editing.value.id,data);else await platformApi.createOfficer(data);modal.value=false;await load(result.value.page||1)}catch(e:any){error.value=e.response?.data?.detail||'Could not save officer'}finally{saving.value=false}}
function remove(o:any){pendingDelete.value=o}async function confirmRemove(){if(!pendingDelete.value)return;try{await platformApi.deleteOfficer(pendingDelete.value.id);pendingDelete.value=null;await load(result.value.page||1)}catch(e:any){error.value=e.response?.data?.detail||'Could not delete officer'}}
onMounted(()=>load());</script>
